package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import dustin.broadcaster.*;
import dustin.cex.domains.bitcoin.*;
import dustin.cex.shared.http.EngineWithdrawalClient;
import dustin.confirmer.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;

/** 여섯 확인 머리부터 엔진 COMPLETE와 Kafka 금융 완료·비용 분개까지 한 출금의 마지막 경계를 검증한다. */
class BitcoinPayoutCompletionIntegrationTest extends BitcoinPayoutCandidatesTestSupport {
    @Autowired BitcoinSignerEnvelopeCrypto signerCrypto;@Autowired BitcoinPayoutCompletionDispatches completions;String txid;UUID engine;long sequence;
    @BeforeEach void confirmedReady(){var candidate=readyNative(approved.payload().id());payouts.commit(approved.payload().id());txid=candidate.payload().prepared().unsignedTxid();var signer=mock(dustin.signer.BitcoinSignerRpcClient.class);when(signer.sign(any())).thenReturn(new dustin.signer.BitcoinSignerRpcClient.Signed(txid,"020000000001"+"00".repeat(100),"cHNidP8BAAA="));new dustin.signer.BitcoinSigningService(jdbc,signerCrypto,json,audit,signer,manager).processNext();var broadcaster=mock(BitcoinBroadcastRpcClient.class);when(broadcaster.publish(anyString(),anyString())).thenReturn(new BitcoinBroadcastRpcClient.Result(BitcoinBroadcastRpcClient.Status.ACCEPTED,txid));new BitcoinBroadcastService(jdbc,signerCrypto,audit,broadcaster,manager).processNext();var observer=mock(BitcoinConfirmationRpcClient.class);when(observer.observe(txid)).thenReturn(new BitcoinConfirmationRpcClient.Result(BitcoinConfirmationRpcClient.Status.CONFIRMED,txid,"a".repeat(64),100,6,"b".repeat(64)));new BitcoinConfirmationService(jdbc,audit,observer,manager).processNext();var row=jdbc.queryForMap("SELECT engine_id,event_id FROM bitcoin_withdrawal_reservation_events WHERE withdrawal_id=?",withdrawal);engine=(UUID)row.get("engine_id");sequence=Long.parseLong(((String)row.get("event_id")).split(":")[1])+1;clearInvocations(engineWithdrawal);when(engineWithdrawal.execute(any())).thenReturn(EngineWithdrawalClient.Outcome.DURABLY_COMPLETED);}
    @Test void sixConfirmationHeadDispatchesExactGrossComplete(){var result=completions.processNext().orElseThrow();assertEquals(EngineWithdrawalClient.Outcome.DURABLY_COMPLETED,result.transport());org.mockito.Mockito.verify(engineWithdrawal).execute(new EngineWithdrawalClient.Command(withdrawal,customer.getId(),"BTC",GROSS,EngineWithdrawalClient.Action.COMPLETE));assertEquals(1,count("bitcoin_payout_completion_attempts"));assertEquals(1,count("bitcoin_payout_completion_results"));}
    @Test void httpCompletionAloneDoesNotChangeTheFinancialHold(){completions.processNext();amount(new BigDecimal("0.00999900"),GROSS);assertEquals(0,count("bitcoin_withdrawal_completion_events"));}
    @Test void durableKafkaCompletionDebitsOnceAndSeparatesFeeFromMinerCost(){completions.processNext();String raw=event(withdrawal,engine,"withdrawal_completed",sequence);events.consumeOrderEvent(raw);events.consumeOrderEvent(raw);amount(new BigDecimal("0.00999900"),BigDecimal.ZERO);assertEquals(1,count("bitcoin_withdrawal_completion_events"));assertEquals(0,new BigDecimal("0.00000100").compareTo(sum("SELECT coalesce(sum(delta),0) FROM ledger_entries WHERE operation_key=? AND owner_id=0 AND bucket='FEE'","engine:"+engine+":"+sequence+":0")));assertEquals(0,new BigDecimal("-0.00000282").compareTo(sum("SELECT coalesce(sum(delta),0) FROM ledger_entries WHERE operation_key=? AND owner_id=0 AND bucket='FEE'","btc:withdrawal:miner-fee:"+withdrawal)));}
    @Test void completionFromAnotherEngineCannotDebitTheHold(){completions.processNext();assertThrows(IllegalStateException.class,()->events.consumeOrderEvent(event(withdrawal,UUID.randomUUID(),"withdrawal_completed",sequence)));amount(new BigDecimal("0.00999900"),GROSS);assertEquals(0,count("bitcoin_withdrawal_completion_events"));}
    @Test void unknownHttpOutcomeKeepsTheSameHoldForRetry(){when(engineWithdrawal.execute(any())).thenReturn(EngineWithdrawalClient.Outcome.OUTCOME_UNKNOWN);assertEquals(EngineWithdrawalClient.Outcome.OUTCOME_UNKNOWN,completions.processNext().orElseThrow().transport());assertTrue(completions.processNext().isEmpty());amount(new BigDecimal("0.00999900"),GROSS);}
    @Test void missingCompletionAuditRollsBackBalanceLedgerReceiptAndInbox(){completions.processNext();doNothing().when(audit).record(isNull(),eq("BTC_WITHDRAWAL_COMPLETED"),anyString(),eq("SUCCESS"),anyString());try{assertThrows(org.springframework.dao.DataAccessException.class,()->events.consumeOrderEvent(event(withdrawal,engine,"withdrawal_completed",sequence)));}finally{reset(audit);}amount(new BigDecimal("0.00999900"),GROSS);assertEquals(0,count("bitcoin_withdrawal_completion_events"));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM engine_event_receipts WHERE event_id=?",Long.class,engine+":"+sequence+":0"));}
    @Test void completionHistoryCannotBeChangedOrDeleted(){completions.processNext();events.consumeOrderEvent(event(withdrawal,engine,"withdrawal_completed",sequence));for(String table:List.of("bitcoin_payout_completion_attempts","bitcoin_payout_completion_results","bitcoin_withdrawal_completion_events"))for(String sql:List.of("UPDATE "+table+" SET created_txid=0","DELETE FROM "+table,"TRUNCATE "+table+" CASCADE"))assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.execute(sql));}
    @Test void twoCompletionConsumersSendOneCommand()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var start=new CountDownLatch(1);Callable<Optional<BitcoinPayoutCompletionDispatches.Execution>> call=()->{start.await();return completions.processNext();};var one=pool.submit(call);var two=pool.submit(call);start.countDown();assertEquals(1,List.of(one.get(15,TimeUnit.SECONDS),two.get(15,TimeUnit.SECONDS)).stream().filter(Optional::isPresent).count());}org.mockito.Mockito.verify(engineWithdrawal,times(1)).execute(any());}
    @Test void independentReconciliationMatchesCompletionAndMinerExpense(){completions.processNext();String time=jdbc.queryForObject("SELECT event_time FROM bitcoin_withdrawal_reservation_events WHERE withdrawal_id=?",String.class,withdrawal);String reserve=eventAt("withdrawal_reserved",sequence-1,time),complete=event(withdrawal,engine,"withdrawal_completed",sequence);events.consumeOrderEvent(complete);var source=mock(dustin.cex.domains.reconciliation.EngineAuditClient.class);when(source.page(eq(0L),isNull(),isNull())).thenReturn(json.valueToTree(Map.of("engine_id",engine.toString(),"through",sequence,"next_after",sequence,"events",List.of(reserve,complete))));var report=new dustin.cex.domains.reconciliation.ReconciliationService(jdbc,source,submissions,manager).run();assertEquals("MATCHED",report.status(),jdbc.queryForList("SELECT * FROM reconciliation_issues WHERE run_id=?",report.id()).toString());}
    /** 상위 지급 준비 시험은 엔진 호출을 금지하지만 이 클래스는 검증한 완료 호출 자체가 시험 대상이다. */
    @AfterEach @Override void neverPayOrDiscloseInAudit(){}
    String eventAt(String type,long position,String time){var data=new LinkedHashMap<String,Object>();data.put("event_id",engine+":"+position+":0");data.put("engine_id",engine);data.put("event_type",type);data.put("withdrawal_id",withdrawal);data.put("user_id",customer.getId());data.put("asset","BTC");data.put("amount",GROSS.toPlainString());data.put("timestamp",time);return json.writeValueAsString(data);}
    BigDecimal sum(String sql,String key){return jdbc.queryForObject(sql,BigDecimal.class,key);}
}
